import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Narrow reuse of existing zombie factory, three corpse consumers and owner-list publication. */
public final class CreateZombieMethods {
 static final String P="local/lito381/server/",H=P+"NativeCreateZombieLifecycle",PC=P+"ClientSession";
 static ClassNode read(JarFile j,String n)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(n+".class")).readAllBytes()).accept(c,ClassReader.SKIP_DEBUG);return c;}
 static byte[] bytes(ClassNode c){var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static AbstractInsnNode next(AbstractInsnNode n){do{n=n.getNext();}while(n!=null&&n.getOpcode()<0);return n;}
 static void patch(ClassNode c){
  if(c.name.equals(P+"BattleQuestEncounter$Snapshot")||c.name.equals(P+"BattleTimeAttackEncounter$Snapshot")){if(c.fields.stream().anyMatch(f->f.name.equals("nativeZombieCorpseActor")))throw new AssertionError("existing corpse actor field");c.fields.add(new FieldNode(ACC_PRIVATE,"nativeZombieCorpseActor","Ljava/lang/Object;",null,null));c.fields.add(new FieldNode(ACC_PRIVATE,"nativeZombieCorpseBag","L"+P+"RuntimeInventory;",null,null));return;}
  if(c.name.equals(P+"BattleQuestEncounter")||c.name.equals(P+"BattleTimeAttackEncounter")){int count=0,revive=0;for(var m:c.methods){if(m.name.equals("resurrectCorpse")&&(m.desc.startsWith("(JIJI)")||m.desc.startsWith("(JJI)"))){int corpse=-1;for(var i:m.instructions)if(i instanceof MethodInsnNode call&&call.name.equals("findCorpse")){var store=next(i);if(!(store instanceof VarInsnNode v)||v.getOpcode()!=ASTORE)throw new AssertionError("corpse return local");corpse=v.var;}if(corpse<0)throw new AssertionError("existing corpse local");String result=m.desc.substring(m.desc.indexOf(')')+1);for(var i:m.instructions.toArray())if(i.getOpcode()==ARETURN){var x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new VarInsnNode(ALOAD,corpse));x.add(new InsnNode(c.name.equals(P+"BattleQuestEncounter")?ICONST_1:ICONST_2));x.add(new MethodInsnNode(INVOKESTATIC,H,"resurrected","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;I)Ljava/lang/Object;",false));x.add(new TypeInsnNode(CHECKCAST,result.substring(1,result.length()-1)));m.instructions.insertBefore(i,x);}revive++;}if(m.name.equals("rememberCorpse")){var x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new VarInsnNode(ALOAD,1));x.add(new InsnNode(c.name.equals(P+"BattleQuestEncounter")?ICONST_1:ICONST_2));x.add(new MethodInsnNode(INVOKESTATIC,H,"retainCorpse","(Ljava/lang/Object;Ljava/lang/Object;I)V",false));m.instructions.insert(x);count++;}}if(count!=1||revive!=1)throw new AssertionError("one existing corpse-retention/resurrection entrance "+count+"/"+revive);return;}
  if(c.name.equals(P+"GameHub")){int count=0;for(var m:c.methods)if(m.name.equals("consumeClassicWorldMonsterCorpse")&&m.desc.equals("(IIJ)L"+P+"ClassicWorldMonsterPopulation$Snapshot;")){m.instructions.clear();m.tryCatchBlocks.clear();m.localVariables=null;m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new VarInsnNode(ILOAD,1));m.instructions.add(new VarInsnNode(ILOAD,2));m.instructions.add(new VarInsnNode(LLOAD,3));m.instructions.add(new MethodInsnNode(INVOKESTATIC,H,"worldCore","(L"+P+"GameHub;IIJ)L"+P+"ClassicWorldMonsterPopulation$Snapshot;",false));m.instructions.add(new InsnNode(ARETURN));count++;}if(count!=1)throw new AssertionError("existing World corpse consumer="+count);return;}
  if(c.name.equals(P+"BattleCompanion")){int count=0;for(var m:c.methods)if(m.name.equals("zombie"))for(var i:m.instructions.toArray())if(i instanceof FieldInsnNode f&&f.owner.equals(P+"BattleCompanion$Kind")&&f.name.equals("SUMMON")){f.name="TAMED";count++;}if(count!=1)throw new AssertionError("existing zombie Source kind="+count);return;}
  var original=c.methods.stream().filter(m->m.name.equals("publishCreatedZombie")).findFirst().orElseThrow();original.name="nativeSourceZombiePublication";var publication=new MethodNode(ASM9,ACC_PRIVATE,"publishCreatedZombie",original.desc,null,original.exceptions.toArray(String[]::new));publication.instructions.add(new VarInsnNode(ALOAD,0));publication.instructions.add(new VarInsnNode(ALOAD,1));publication.instructions.add(new VarInsnNode(ALOAD,2));publication.instructions.add(new MethodInsnNode(INVOKESTATIC,H,"publishCreated","(L"+PC+";L"+P+"BattleCompanion;Ljava/util/List;)V",false));publication.instructions.add(new InsnNode(RETURN));c.methods.add(publication);
  int roots=0;for(var m:c.methods)if(m.name.equals("nativeMaterialZombieBody")){roots++;int factories=0,consumers=0,lists=0,lookups=0,petLocal=-1;for(var i:m.instructions.toArray())if(i instanceof MethodInsnNode call&&call.owner.equals(P+"BattleCompanion")&&call.name.equals("zombie")){var store=next(i);if(!(store instanceof VarInsnNode v)||v.getOpcode()!=ASTORE)throw new AssertionError("factory local");petLocal=v.var;call.owner=H;call.name="factory";factories++;}if(factories!=1)throw new AssertionError("one existing zombie factory");
   for(var i:m.instructions.toArray())if(i instanceof MethodInsnNode call){
    if(call.owner.equals(P+"GameHub")&&call.name.equals("timeAttackCorpse")){call.setOpcode(INVOKESTATIC);call.owner=H;call.name="timeCorpse";call.desc="(L"+P+"GameHub;"+call.desc.substring(1);call.itf=false;lookups++;}
    else if(call.owner.equals(P+"GameHub")&&Set.of("consumeQuestCorpse","consumeTimeAttackCorpse","consumeClassicWorldMonsterCorpse").contains(call.name)){boolean world=call.name.equals("consumeClassicWorldMonsterCorpse");var x=new InsnList();x.add(new VarInsnNode(ALOAD,petLocal));if(world)x.add(new VarInsnNode(ALOAD,0));m.instructions.insertBefore(i,x);String arguments=call.desc.substring(1,call.desc.indexOf(')'));String result=call.desc.substring(call.desc.indexOf(')')+1);call.setOpcode(INVOKESTATIC);call.owner=H;call.name=world?"consumeWorld":call.name.equals("consumeQuestCorpse")?"consumeQuest":"consumeTime";call.desc="(L"+P+"GameHub;"+arguments+"L"+P+"BattleCompanion;"+(world?"L"+PC+";":"")+")"+result;call.itf=false;consumers++;}
    else if(call.owner.equals("java/util/List")&&call.name.equals("add")&&call.desc.equals("(Ljava/lang/Object;)Z")){call.setOpcode(INVOKESTATIC);call.owner=H;call.name="published";call.desc="(Ljava/util/List;Ljava/lang/Object;)Z";call.itf=false;lists++;}
   }if(consumers!=3||lists!=1||lookups!=2)throw new AssertionError("exact zombie corpse/list edges "+consumers+"/"+lists);
  }if(roots!=1)throw new AssertionError("one existing zombie body");
 }
 public static void main(String[]a)throws Exception{try(var old=new JarFile(a[1])){for(String owner:List.of(PC,P+"BattleCompanion",P+"GameHub",P+"BattleQuestEncounter",P+"BattleTimeAttackEncounter",P+"BattleQuestEncounter$Snapshot",P+"BattleTimeAttackEncounter$Snapshot")){var c=read(old,owner);patch(c);var expected=bytes(c);if(a[0].equals("splice")){var p=Path.of(a[2]).resolve(owner+".class");Files.createDirectories(p.getParent());Files.write(p,expected);}else try(var candidate=new JarFile(a[2])){if(!Arrays.equals(expected,bytes(read(candidate,owner))))throw new AssertionError("exact zombie edge regeneration "+owner);}}System.out.println("PASS existing factory/corpse/list edges, Source TAMED kind and existing World corpse consumer only; all other members retained");}}
}
